    private void confirm(String action,Member m){if(PartyMod.runtime.state.get(m.name)!=m)return;if(!PartyMod.config.confirmActions&&!action.equals("delete")){execute(action,m);return;}confirm=action;confirmationTicket=new MemberTicket(PartyMod.runtime.state,m);confirmName=m.name;confirmGeneration=PartyMod.runtime.state.generation;confirmMembership=m.membershipId;}
    private void execute(String action,Member m){switch(action){case "remove":PartyMod.runtime.remove(m);break;case "block":PartyMod.runtime.block(m);break;case "ignore":PartyMod.runtime.ignore(m);break;case "delete":PartyMod.runtime.store.delete(m);m.approved=false;m.dismissedFingerprint="";loadNote();PartyMod.runtime.reassess();break;default:break;}}
