    @Override protected void mouseClicked(int x,int y,int button)throws IOException{if(button!=0)return;reconcileSelection();int mx=mx(x),my=my(y);if(confirm.isEmpty()){if(tab.equals("Players")||tab.equals("Review queue")){search.mouseClicked(mx,my,button);note.mouseClicked(mx,my,button);}if(tab.equals("Event desk"))waitName.mouseClicked(mx,my,button);}for(Hit hit:new ArrayList<>(hits))if(hit.has(mx,my)){hit.action.run();break;}}
    @Override protected void keyTyped(char typed,int key)throws IOException{reconcileSelection();if(!confirm.isEmpty()){if(key==Keyboard.KEY_ESCAPE)confirm="";return;}if(key==Keyboard.KEY_ESCAPE){mc.displayGuiScreen(null);return;}if((tab.equals("Players")||tab.equals("Review queue"))&&search.textboxKeyTyped(typed,key)){refreshOrder();return;}if((tab.equals("Players")||tab.equals("Review queue"))&&note.textboxKeyTyped(typed,key)){Member m=PartyMod.runtime.state.get(selected);if(m!=null){PartyMod.runtime.store.record(m).note=note.getText();PartyMod.runtime.store.touch();}return;}if(tab.equals("Event desk")&&waitName.textboxKeyTyped(typed,key))return;if(key==Keyboard.KEY_UP||key==Keyboard.KEY_DOWN){int next=order.indexOf(selected)+(key==Keyboard.KEY_DOWN?1:-1);if(next>=0&&next<order.size()){selected=order.get(next);scroll=Math.max(0,Math.min(next,Math.max(0,order.size()-6)));detailScroll=0;loadNote();}}if(key==Keyboard.KEY_TAB){String next=TABS[(Arrays.asList(TABS).indexOf(tab)+1)%TABS.length];tab=next;scroll=0;refreshOrder();}}
    @Override public void handleMouseInput()throws IOException{super.handleMouseInput();int wheel=Mouse.getEventDWheel();if(wheel==0||!confirm.isEmpty())return;int x=Mouse.getEventX()*width/mc.displayWidth,y=height-Mouse.getEventY()*height/mc.displayHeight-1;if(mx(x)>569&&(tab.equals("Players")||tab.equals("Review queue")))detailScroll+=wheel<0?2:-2;else scroll=Math.max(0,scroll+(wheel<0?1:-1));}
    private void button(int x,int y,int w,int h,String label,Runnable action,int mx,int my,boolean primary){boolean hover=mx>=x&&my>=y&&mx<x+w&&my<y+h;round(x,y,w,h,6,primary?(hover?0xffb0a2ff:ACCENT):(hover?0xff30394f:SOFT));int tw=fontRendererObj.getStringWidth(label);text(label,x+(w-tw)/2,y+(h-8)/2,primary?0xff171927:TEXT,1);hits.add(new Hit(x,y,w,h,action));}
