    private void head(Member m,int x,int y){NetworkPlayerInfo info=mc.getNetHandler()==null?null:mc.getNetHandler().getPlayerInfo(m.name);if(info!=null){GlStateManager.color(1,1,1,1);mc.getTextureManager().bindTexture(info.getLocationSkin());Gui.drawScaledCustomSizeModalRect(x,y,8,8,8,8,24,24,64,64);}else{round(x,y,24,24,6,SOFT);text(m.name.substring(0,1).toUpperCase(Locale.ROOT),x+8,y+8,ACCENT,1);}}
    private String date(Long time){return time==null||time<=0?"Unknown":new SimpleDateFormat("dd MMM yyyy",Locale.ROOT).format(new Date(time));}
    private String number(Number n){return n==null?"Unknown":n instanceof Double?String.format(Locale.ROOT,"%.2f",n.doubleValue()):n.toString();}
