    public static void round(float x,float y,float w,float h,float radius,int color){boolean cull=GL11.glIsEnabled(GL11.GL_CULL_FACE),blend=GL11.glIsEnabled(GL11.GL_BLEND),texture=GL11.glIsEnabled(GL11.GL_TEXTURE_2D);int src=GL11.glGetInteger(32969),dst=GL11.glGetInteger(32968),srcAlpha=GL11.glGetInteger(32971),dstAlpha=GL11.glGetInteger(32970);GlStateManager.disableCull();GlStateManager.enableBlend();GlStateManager.disableTexture2D();GlStateManager.tryBlendFuncSeparate(770,771,1,0);GlStateManager.color((color>>16&255)/255f,(color>>8&255)/255f,(color&255)/255f,(color>>>24)/255f);GL11.glBegin(GL11.GL_TRIANGLE_FAN);GL11.glVertex2f(x+w/2,y+h/2);for(int corner=0;corner<4;corner++){float cx=corner==0||corner==3?x+radius:x+w-radius,cy=corner<2?y+radius:y+h-radius;for(int step=0;step<=8;step++){double angle=Math.toRadians(180+corner*90+step*90/8.0);GL11.glVertex2f(cx+(float)Math.cos(angle)*radius,cy+(float)Math.sin(angle)*radius);}}GL11.glVertex2f(x,y+radius);GL11.glEnd();if(cull)GlStateManager.enableCull();if(texture)GlStateManager.enableTexture2D();else GlStateManager.disableTexture2D();if(blend)GlStateManager.enableBlend();else GlStateManager.disableBlend();GlStateManager.tryBlendFuncSeparate(src,dst,srcAlpha,dstAlpha);GlStateManager.color(1,1,1,1);}
    public static void drawToast(Notifications.Entry entry,int width){Minecraft mc=Minecraft.getMinecraft();String label=mc.fontRendererObj.trimStringToWidth(entry.text,280);int w=Math.min(310,mc.fontRendererObj.getStringWidth(label)+24);round(width-w-14,16,w,43,7,CARD);mc.fontRendererObj.drawString(entry.operational?"PARTY UPDATE":"PARTY REVIEW",width-w-2,24,entry.operational?AMBER:ACCENT);mc.fontRendererObj.drawString(label,width-w-2,39,TEXT);}
